window.PHILO_DOC={"v":1,"slug":"philo-tle","titre":"Mon livret de philosophie — Terminale A4","toc":[{"niv":"section","titre":"Avant-propos","sec":"s1"},{"niv":"subsection","titre":"1. Ce que l’examinateur te demande","sec":"s1","ancre":"t2"},{"niv":"subsection","titre":"2. Comment est organisé ce livret?","sec":"s1","ancre":"t3"},{"niv":"subsection","titre":"3. Comment travailler avec ce livret?","sec":"s1","ancre":"t4"},{"niv":"part","titre":"Première partie — La méthode du commentaire","sec":"s2"},{"niv":"subsection","titre":"1. Les deux exercices de l’épreuve","sec":"s2","ancre":"t6"},{"niv":"subsection","titre":"2. Les mots de la consigne, expliqués simplement","sec":"s2","ancre":"t7"},{"niv":"subsection","titre":"3. Le commentaire philosophique : sept paragraphes","sec":"s2","ancre":"t8"},{"niv":"subsection","titre":"4. La conclusion et l’intérêt philosophique","sec":"s2","ancre":"t9"},{"niv":"subsection","titre":"5. Méthodologie approfondie","sec":"s2","ancre":"t10"},{"niv":"subsection","titre":"6. Lire un texte philosophique pas à pas","sec":"s2","ancre":"t11"},{"niv":"subsection","titre":"7. Grille d’auto-évaluation du commentaire","sec":"s2","ancre":"t12"},{"niv":"subsection","titre":"8. Les erreurs qui coûtent des points","sec":"s2","ancre":"t13"},{"niv":"subsection","titre":"9. Répartir son temps (4 heures, proportions indicatives)","sec":"s2","ancre":"t14"},{"niv":"part","titre":"Deuxième partie — Textes à commenter","sec":"s3"},{"niv":"subsection","titre":"1. Les sept maquettes de rédaction","sec":"s3","ancre":"t16"},{"niv":"subsection","titre":"2. Dégager toi-même ta maquette : souligner les connecteurs","sec":"s3","ancre":"t17"},{"niv":"subsection","titre":"A Marcien Towa","sec":"s3","ancre":"t18"},{"niv":"section","titre":"Chapitre 1 — La philosophie africaine et l’ethnophilosophie","sec":"s4"},{"niv":"section","titre":"Chapitre 2 — Négritude, assimilation et libération","sec":"s5"},{"niv":"section","titre":"Chapitre 3 — Révolution, puissance et affirmation de soi","sec":"s6"},{"niv":"section","titre":"Chapitre 4 — Philosophie, science et raison","sec":"s7"},{"niv":"section","titre":"Chapitre 5 — Philosophie, religion et pensée critique","sec":"s8"},{"niv":"subsection","titre":"B Ebénézer Njoh-Mouelle","sec":"s8","ancre":"t24"},{"niv":"section","titre":"Chapitre 6 — La liberté","sec":"s9"},{"niv":"section","titre":"Chapitre 7 — Avoir, être et développement","sec":"s10"},{"niv":"section","titre":"Chapitre 8 — Bien-être, bonheur et accomplissement de soi","sec":"s11"},{"niv":"section","titre":"Chapitre 9 — Médiocrité et excellence","sec":"s12"},{"niv":"section","titre":"Chapitre 10 — Culture, tradition et modernité","sec":"s13"},{"niv":"section","titre":"Chapitre 11 — Religion, spiritualité et morale","sec":"s14"},{"niv":"section","titre":"Chapitre 12 — L’art et l’artiste","sec":"s15"},{"niv":"part","titre":"Troisième partie — La dissertation","sec":"s16"},{"niv":"subsection","titre":"1. Les deux types de sujets","sec":"s16","ancre":"t33"},{"niv":"subsection","titre":"2. Le plan complet de la dissertation","sec":"s16","ancre":"t34"},{"niv":"subsection","titre":"3. L’introduction : partir de la polémique","sec":"s16","ancre":"t35"},{"niv":"subsection","titre":"4. Le corps de la dissertation","sec":"s16","ancre":"t36"},{"niv":"subsection","titre":"5. La conclusion : une solution personnelle et contextualisée","sec":"s16","ancre":"t37"},{"niv":"subsection","titre":"6. Ta maquette de dissertation : sur une copie à grands carreaux","sec":"s16","ancre":"t38"},{"niv":"subsection","titre":"7. Grille d’auto-évaluation de la dissertation","sec":"s16","ancre":"t39"},{"niv":"section","titre":"Chapitre 13 — Deux périodes de l’histoire de la philosophie","sec":"s17"},{"niv":"section","titre":"Chapitre 14 — L’argumentation","sec":"s18"},{"niv":"section","titre":"Chapitre 15 — La démonstration et la méthode","sec":"s19"},{"niv":"section","titre":"Chapitre 16 — Passion et raison","sec":"s20"},{"niv":"section","titre":"Chapitre 17 — La liberté et la responsabilité","sec":"s21"},{"niv":"section","titre":"Chapitre 18 — La nature et la culture","sec":"s22"},{"niv":"section","titre":"Chapitre 19 — L’art et le travail","sec":"s23"},{"niv":"section","titre":"Chapitre 20 — La science","sec":"s24"},{"niv":"section","titre":"Chapitre 21 — Les types de science","sec":"s25"},{"niv":"section","titre":"Chapitre 22 — La vérité","sec":"s26"},{"niv":"section","titre":"Chapitre 23 — L’espace et le temps","sec":"s27"},{"niv":"section","titre":"Chapitre 24 — L’existence et la mort","sec":"s28"},{"niv":"section","titre":"Chapitre 25 — Dieu et la religion","sec":"s29"},{"niv":"section","titre":"Chapitre 26 — L’homme et l’histoire","sec":"s30"},{"niv":"part","titre":"Quatrième partie — S’entraîner à l’épreuve complète","sec":"s31"},{"niv":"subsection","titre":"1. Les sujets du Baccalauréat A4 de 2022 à 2025, corrigés","sec":"s31","ancre":"t55"},{"niv":"subsection","titre":"2. Huit épreuves types du Baccalauréat","sec":"s31","ancre":"t56"},{"niv":"subsection","titre":"3. Banque de sujets de dissertation","sec":"s31","ancre":"t57"},{"niv":"subsection","titre":"4. Plan de travail annuel","sec":"s31","ancre":"t58"},{"niv":"section","titre":"Corrigés","sec":"s32"},{"niv":"subsection","titre":"5. Corrigés des troisième et quatrième parties","sec":"s32","ancre":"t60"},{"niv":"part","titre":"Bibliographie des titres phares","sec":"s33","ancre":"t61"}],"labels":{"part:1":"s2","part:2":"s3","exo:.1":"s3","chap:CHAPITRE-1":"s4","exo:1.1":"s4","exo:1.2":"s4","exo:1.3":"s4","exo:1.4":"s4","exo:1.5":"s4","chap:CHAPITRE-2":"s5","exo:2.1":"s5","exo:2.2":"s5","exo:2.3":"s5","exo:2.4":"s5","exo:2.5":"s5","chap:CHAPITRE-3":"s6","exo:3.1":"s6","exo:3.2":"s6","exo:3.3":"s6","exo:3.4":"s6","exo:3.5":"s6","chap:CHAPITRE-4":"s7","exo:4.1":"s7","exo:4.2":"s7","exo:4.3":"s7","exo:4.4":"s7","exo:4.5":"s7","chap:CHAPITRE-5":"s8","exo:5.1":"s8","exo:5.2":"s8","exo:5.3":"s8","exo:5.4":"s8","exo:5.5":"s8","exo:.2":"s8","chap:CHAPITRE-6":"s9","exo:6.1":"s9","exo:6.2":"s9","exo:6.3":"s9","exo:6.4":"s9","exo:6.5":"s9","chap:CHAPITRE-7":"s10","exo:7.1":"s10","exo:7.2":"s10","exo:7.3":"s10","exo:7.4":"s10","exo:7.5":"s10","chap:CHAPITRE-8":"s11","exo:8.1":"s11","exo:8.2":"s11","exo:8.3":"s11","exo:8.4":"s11","exo:8.5":"s11","chap:CHAPITRE-9":"s12","exo:9.1":"s12","exo:9.2":"s12","exo:9.3":"s12","exo:9.4":"s12","exo:9.5":"s12","chap:CHAPITRE-10":"s13","exo:10.1":"s13","exo:10.2":"s13","exo:10.3":"s13","exo:10.4":"s13","exo:10.5":"s13","chap:CHAPITRE-11":"s14","exo:11.1":"s14","exo:11.2":"s14","exo:11.3":"s14","exo:11.4":"s14","exo:11.5":"s14","chap:CHAPITRE-12":"s15","exo:12.1":"s15","exo:12.2":"s15","exo:12.3":"s15","exo:12.4":"s15","exo:12.5":"s15","part:3":"s16","chap:CHAPITRE-13":"s17","exo:D13.1":"s17","exo:D13.2":"s17","exo:AN13.1":"s17","chap:CHAPITRE-14":"s18","exo:D14.1":"s18","chap:CHAPITRE-15":"s19","exo:D15.1":"s19","chap:CHAPITRE-16":"s20","exo:D16.1":"s20","exo:D16.2":"s20","chap:CHAPITRE-17":"s21","exo:D17.1":"s21","exo:D17.2":"s21","exo:AN17.1":"s21","chap:CHAPITRE-18":"s22","exo:D18.1":"s22","exo:D18.2":"s22","exo:AN18.1":"s22","exo:AN18.2":"s22","chap:CHAPITRE-19":"s23","exo:D19.1":"s23","exo:D19.2":"s23","exo:AN19.1":"s23","exo:AN19.2":"s23","exo:AN19.3":"s23","exo:AN19.4":"s23","chap:CHAPITRE-20":"s24","exo:D20.1":"s24","exo:D20.2":"s24","exo:AN20.1":"s24","chap:CHAPITRE-21":"s25","exo:D21.1":"s25","exo:D21.2":"s25","chap:CHAPITRE-22":"s26","exo:D22.1":"s26","exo:D22.2":"s26","chap:CHAPITRE-23":"s27","exo:D23.1":"s27","exo:D23.2":"s27","chap:CHAPITRE-24":"s28","exo:D24.1":"s28","exo:D24.2":"s28","chap:CHAPITRE-25":"s29","exo:D25.1":"s29","exo:D25.2":"s29","chap:CHAPITRE-26":"s30","exo:D26.1":"s30","exo:D26.2":"s30","part:4":"s31","corriges":"s32"},"_extrait":true,"sections":[{"id":"s1","kind":"front","num":"","titre":"Avant-propos","sous":"","couleur":"","genre":"","html":"<h1 class=pagetitle k=B03A6A>Avant-propos</h1><div class=ornament style=--o:#D493AD><i></i><b></b><i></i></div><p>Cher élève,</p><p>Ce livret a un seul but : te rendre capable de réussir toute l’épreuve de philosophie du Baccalauréat A : le <b>commentaire </b>d’un texte de Marcien Towa (<i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>) ou d’Ebénézer Njoh-Mouelle (<i>De la médiocrité à l’excellence</i>), et la <b>dissertation </b>sur les notions du programme. Il suit la fiche de progression harmonisée de Terminale A (38 leçons).</p><h3 class=hone k=B03A6A><span class=hico><i class=fa>&#xF140;</i></span><span class=hnum>1.</span> Ce que l’examinateur te demande</h3><p><a id=t2></a> Baccalauréat ESG, série A4 · durée : 4 heures · coefficient 4. <b>Le candidat traite obligatoirement les deux parties de l’épreuve.</b></p><div class=tabbloc><div class=\"tr hdr\" style=\"grid-template-columns:0.620fr 1.380fr 3.7em;background:#B03B6B\"><div class=td><span class=th>Partie de l’épreuve</span></div><div class=td><span class=th>Ce qu’il faut faire</span></div><div class=\"td c\"><span class=th>Points</span></div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr 3.7em;background:#F4F4F7\"><div class=td><span k=7F2A4C><b>Partie A — Évaluation des ressources</b></span></div><div class=td>Commentaire d’un texte de Towa ou de Njoh-Mouelle, en 15 à 25 lignes : définir le problème (1,5 pt), étude analytique (2 pts), réfutation (2 pts), réinterprétation (2 pts), conclusion (1,5 pt).</div><div class=\"td c\">9</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr 3.7em;background:#FFFFFF\"><div class=td><span k=7F2A4C><b>Partie B — Évaluation des compétences</b></span></div><div class=td>Dissertation en trois tâches : introduction (3 pts), analyse dialectique (3 pts), conclusion avec une solution personnelle et contextualisée (3 pts).</div><div class=\"td c\">9</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr 3.7em;background:#F4F4F7\"><div class=td><span k=7F2A4C><b>Présentation</b></span></div><div class=td>Copie propre, paragraphes, orthographe.</div><div class=\"td c\">2</div></div></div><h3 class=hone k=B03A6A><span class=hico><i class=fa>&#xF140;</i></span><span class=hnum>2.</span> Comment est organisé ce livret?</h3><p><a id=t3></a></p><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div><b>Première partie : </b>la méthode du commentaire (les sept paragraphes, les mots de la consigne, l’intérêt philosophique, la lecture pas à pas, l’auto-évaluation).</div></li></ul><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div><b>Deuxième partie : </b>les deux œuvres au programme. Elle s’ouvre par <b>sept maquettes </b>de rédaction et par la méthode pour <b>dégager ta propre maquette </b>en soulignant les connecteurs. Pour chaque auteur : sa vie et sa posture, l’œuvre en un coup d’œil, puis <b>soixante textes </b>en douze chapitres. Dans chaque chapitre, <b>le premier texte est commenté en entier</b>; les quatre autres sont <b>orientés </b>et proposent des articulations, des réfutations avec leurs auteurs, des réinterprétations avec leurs héritiers et l’intérêt philosophique. Chaque chapitre se termine par <b>deux textes d’entraînement</b> à retrouver dans l’œuvre (bornes « début… fin »).</div></li></ul><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div><b>Troisième partie : </b>la méthode de la dissertation et une fiche par chapitre de la progression (problèmes, thèses, auteurs, exemples), des exercices d’analyse de sujet, des citations et des sujets d’annales. <b>Six chapitres </b>(13, 16, 17, 18, 19 et 23) comportent <b>un devoir entièrement rédigé</b>, dont les connecteurs sont soulignés.</div></li></ul><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div><b>Quatrième partie : </b>les sujets du Bac de 2022 à 2025 corrigés, huit épreuves types et une banque de sujets. En fin de livret : le plan de travail annuel et les corrigés.</div></li></ul><h3 class=hone k=B03A6A><span class=hico><i class=fa>&#xF140;</i></span><span class=hnum>3.</span> Comment travailler avec ce livret?</h3><p><a id=t4></a></p><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div>Lis la méthode, puis les maquettes. Lis la présentation de l’auteur, l’œuvre en un coup d’œil et la fiche du chapitre : ce sont des pistes, à exploiter, compléter ou remplacer.</div></li></ul><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div>Lis chaque texte deux fois, souligne les mots clés, puis lis le commentaire rédigé ou les pistes. <b>Souligne toi-même les connecteurs </b>du commentaire rédigé pour retrouver la maquette.</div></li></ul><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div>Pour la dissertation, apprends la fiche du chapitre, fais «Analyse ce sujet», puis rédige ton introduction et ton plan avant de lire le devoir rédigé.</div></li></ul><ul class=puces><li><span class=pu k=7F2A4C><i class=fa>&#xF111;</i></span><div>Entraîne-toi en temps limité avec les épreuves types, puis corrige-toi. Refais les exercices ratés après avoir relu le cours.</div></li></ul><div class=\"box callout tagged\" kb=FFF5DA><span class=tag kb=BF542E>À NOTER</span><p><b>Pour aller plus loin : </b>rends-toi sur <b>www.veritas-school.com </b>: corrections approfondies, exercices supplémentaires et réponses à tes questions. Une page du site est consacrée à la correction des exercices de ce livret.</p></div>","libre":true},{"id":"s2","kind":"part","num":"","titre":"Première partie — La méthode du commentaire","sous":"","couleur":"1F2230","genre":"","html":""},{"id":"s3","kind":"part","num":"","titre":"Deuxième partie — Textes à commenter","sous":"","couleur":"1F2230","genre":"","html":""},{"id":"s4","kind":"chap","num":"1","titre":"La philosophie africaine et l’ethnophilosophie","sous":"Marcien Towa · Essai sur la problématique philosophique dans l’Afrique actuelle","couleur":"BF522E","genre":"Chapitre","html":"<div class=chapbanner kb=BF522E><div class=chnum kb=863920><span>CHAPITRE</span><b>1</b></div><div class=chtxt><div class=chtitle>La philosophie africaine et l’ethnophilosophie</div><div class=chsub>Marcien Towa · <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i></div></div></div><p><a id=L-chap_CHAPITRE-1></a></p><h4 class=htwo k=8A3C22><span class=hnum>1.1</span> Fiche du chapitre : des pistes, pas des réponses</h4><div class=tabbloc><div class=\"tr hdr\" style=\"grid-template-columns:0.620fr 1.380fr;background:#BF522E\"><div class=td><span class=th>Rubrique</span></div><div class=td><span class=th>Pistes (à vérifier avec ton cours)</span></div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr;background:#F4F4F7\"><div class=td><span k=8A3C22><b>Problèmes possibles</b></span></div><div class=td>L’existence d’une philosophie africaine ; la valeur de l’ethnophilosophie comme philosophie.</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr;background:#FFFFFF\"><div class=td><span k=8A3C22><b>Idée générale des textes</b></span></div><div class=td>Towa reproche à l’ethnophilosophie d’être une simple revendication, sans esprit critique, donc dogmatique. Philosopher, c’est soumettre l’héritage à la critique et penser notre situation actuelle.</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr;background:#F4F4F7\"><div class=td><span k=8A3C22><b>Mots-clés</b></span></div><div class=td>Ethnophilosophie · négritude · philosophie africaine · ethnologie · critique · dogmatisme · revendication</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr;background:#FFFFFF\"><div class=td><span k=8A3C22><b>Pistes pour la réfutation</b></span></div><div class=td>Placide Tempels (la philosophie bantoue) · Alexis Kagame · Senghor (la négritude comme valeur propre)</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr;background:#F4F4F7\"><div class=td><span k=8A3C22><b>Pistes pour la réinterprétation</b></span></div><div class=td>Contes, proverbes et tradition orale : sont-ils de la philosophie ? · la philosophie enseignée dans nos lycées · la recherche africaine d’aujourd’hui</div></div><div class=tr style=\"grid-template-columns:0.620fr 1.380fr;background:#FFFFFF\"><div class=td><span k=8A3C22><b>Intérêts possibles</b></span></div><div class=td><b>Idéologique : </b>défendre la pensée critique contre la simple revendication culturelle. <b>Méthodologique : </b>montrer la voie d’une philosophie fondée sur la méthode et la critique.</div></div></div><div class=\"box notebox tagged\" kb=F2EDFA><span class=tag kb=7A5EB5>PISTES ET CITATIONS COMPLÉMENTAIRES</span><p><b>Rôle de la philosophie (réfutation) :</b> Aristote (<i>Métaphysique</i>) : les premiers penseurs « poursuivaient le savoir en vue de la seule connaissance et non pour une fin utilitaire ». Hegel (<i>Leçons sur l’histoire de la philosophie</i>) voit dans la philosophie une activité libre, désintéressée, « une sorte de luxe ».</p><p><b>Réinterprétation :</b> Towa (<i>L’Idée d’une philosophie négro-africaine</i>) : « la philosophie n’est pas pure spéculation, mais effort de formulation d’un projet de cité viable ». Njoh-Mouelle (<i>Jalons</i>) : « la philosophie ne recherche pas la vérité pour le plaisir de rechercher la vérité ».</p></div><h4 class=htwo k=8A3C22><span class=hnum>1.2</span> Cinq textes, cinq angles</h4><div class=tabbloc><div class=\"tr hdr\" style=\"grid-template-columns:0.720fr 1.510fr 0.770fr;background:#BF522E\"><div class=td><span class=th>Texte</span></div><div class=td><span class=th>Orientation : la question que le texte permet de poser</span></div><div class=td><span class=th>Source</span></div></div><div class=tr style=\"grid-template-columns:0.720fr 1.510fr 0.770fr;background:#F4F4F7\"><div class=td><span k=8A3C22><b>1.1</b></span></div><div class=td>Pourquoi prouver qu’on a une philosophie ? (l’enjeu politique)</div><div class=td>p. 25</div></div><div class=tr style=\"grid-template-columns:0.720fr 1.510fr 0.770fr;background:#FFFFFF\"><div class=td><span k=8A3C22><b>1.2</b></span></div><div class=td>Que vaut l’ethnophilosophie ? (sa méthode)</div><div class=td>pp. 32-33</div></div><div class=tr style=\"grid-template-columns:0.720fr 1.510fr 0.770fr;background:#F4F4F7\"><div class=td><span k=8A3C22><b>1.3</b></span></div><div class=td>Que doit penser la philosophie en Afrique ? (le présent)</div><div class=td>p. 35</div></div><div class=tr style=\"grid-template-columns:0.720fr 1.510fr 0.770fr;background:#FFFFFF\"><div class=td><span k=8A3C22><b>1.4</b></span></div><div class=td>D’où vient l’élargissement du concept de philosophie ? (l’origine)</div><div class=td>pp. 28-29</div></div><div class=tr style=\"grid-template-columns:0.720fr 1.510fr 0.770fr;background:#F4F4F7\"><div class=td><span k=8A3C22><b>1.5</b></span></div><div class=td>Pourquoi trahit-elle science et philosophie ? (le critère de l’argument)</div><div class=td>p. 31</div></div></div><p><a id=L-exo_1_1></a></p><div class=exo><span class=exob kb=BF542E><i class=fa>&#xF0A4;</i> 1.1</span><div class=exot>Fais de ce texte un commentaire philosophique. « Prouver qu’on a une philosophie pour être reconnu»</div></div><div class=texte style=border-top-color:#C59687><span class=quo k=CFA99C><i class=fa>&#xF10D;</i></span><p>Le problème est l’existence ou la non-existence d’une philosophie africaine, savoir, celui-là même qui est soulevé par les philosophes occidentaux. Ceux-ci, nous l’avons vu, donnaient une réponse négative à la question ainsi posée. Et dans la mesure où la philosophie était considérée comme l’attribut essentiel et indispensable d’une humanité véritable, une telle réponse avait pour effet de justifier l’impérialisme politique et culturel. En reprenant la question, l’intention des penseurs dont nous parlons était au contraire d’y répondre positivement afin de ruiner par là un argument essentiel de l’idéologie impérialiste. Si les nègres ont une philosophie propre, ils sont donc pleinement hommes et doivent jouir de tous les droits d’homme, notamment du droit à l’autonomie aussi bien culturelle que politique.</p><div class=source>— Marcien Towa, <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, CLÉ, Yaoundé, 1971, p. 25.</div></div><p class=copyintro><span k=5F6472>Sur ta copie : un alinéa à chaque paragraphe ; deux lignes sautées entre l’introduction et le développement, puis entre le développement et la conclusion ; les transitions sont des paragraphes à part (en jaune). Les mots soulignés sont les connecteurs, dans le style du </span><span k=5F6472><i>Cours de méthodologie pratique</i></span><span k=5F6472> : chaque copie varie ses tournures pour t’habituer à plusieurs maquettes. Une seule réfutation, une seule réinterprétation.</span></p><div class=badgewrap><span class=badge kb=7A5EB5>COPIE MODÈLE SUR LE TEXTE 1.1</span></div><div class=\"copie f-dev\"><div class=cpar><span class=cplab kb=954024>DP</span><div class=cptxt><span k=7F2A4C><u class=ulw>La</u> <u class=ulw>négation</u> <u class=ulw>de</u> <u class=ulw>l’Afrique</u> <u class=ulw>par</u> <u class=ulw>l’Occident</u> <u class=ulw>impérialiste</u> <u class=ulw>a</u> <u class=ulw>longtemps</u> <u class=ulw>pris</u> <u class=ulw>la</u> <u class=ulw>forme</u> <u class=ulw>d’un</u> <u class=ulw>verdict</u> <u class=ulw>:</u></span> les Noirs n’auraient pas de philosophie. <span k=7F2A4C><u class=ulw>C’est</u> <u class=ulw>dans</u> <u class=ulw>ce</u> <u class=ulw>contexte</u> <u class=ulw>que</u></span> Marcien Towa, <span k=7F2A4C><u class=ulw>dans</u> <u class=ulw>son</u></span> <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i> <span k=7F2A4C>(1971), </span><span k=7F2A4C><u class=ulw>revient</u> <u class=ulw>sur</u> <u class=ulw>l’origine</u> <u class=ulw>de</u> <u class=ulw>la</u> <u class=ulw>question</u></span> « y a-t-il une philosophie africaine ? ». <span k=7F2A4C><u class=ulw>Le</u> <u class=ulw>texte</u> <u class=ulw>soumis</u> <u class=ulw>à</u> <u class=ulw>notre</u> <u class=ulw>réflexion</u> <u class=ulw>a</u> <u class=ulw>pour</u> <u class=ulw>thème</u></span> la portée politique de cette question. <span k=7F2A4C><u class=ulw>Il</u> <u class=ulw>pose</u> <u class=ulw>le</u> <u class=ulw>problème</u> <u class=ulw>de</u></span> la raison pour laquelle on a voulu prouver l’existence d’une philosophie africaine. <span k=7F2A4C><u class=ulw>L’auteur</u> <u class=ulw>y</u> <u class=ulw>soutient</u> <u class=ulw>que</u></span> cette preuve visait à ruiner un argument majeur de l’impérialisme, qui refusait la philosophie aux Noirs pour leur refuser l’humanité. <span k=7F2A4C><u class=ulw>Mais</u></span> une humanité reconnue au prix d’un tel certificat n’est-elle pas déjà soumise au jugement de l’autre ? <span k=7F2A4C><u class=ulw>Néanmoins,</u> <u class=ulw>en</u> <u class=ulw>liant</u> <u class=ulw>la</u> <u class=ulw>pensée</u> <u class=ulw>à</u> <u class=ulw>la</u> <u class=ulw>libération,</u> <u class=ulw>Towa</u> <u class=ulw>ne</u> <u class=ulw>montre-t-il</u> <u class=ulw>pas</u> <u class=ulw>que</u></span> la philosophie n’est jamais un luxe pour un peuple dominé ?</div></div><div class=saute k=954024><i class=fa>&#xF338;</i> tu sautes deux lignes après l’introduction</div><div class=cpar><span class=cplab kb=954024>EA</span><div class=cptxt><span k=7F2A4C><u class=ulw>Dans</u> <u class=ulw>ce</u> <u class=ulw>texte,</u> <u class=ulw>Towa</u> <u class=ulw>s’évertue</u> <u class=ulw>à</u> <u class=ulw>démontrer</u> <u class=ulw>que</u></span> la question de la philosophie africaine est d’abord une arme politique. <span k=7F2A4C><u class=ulw>Pour</u> <u class=ulw>y</u> <u class=ulw>parvenir,</u> <u class=ulw>il</u> <u class=ulw>procède</u> <u class=ulw>en</u> <u class=ulw>deux</u> <u class=ulw>moments.</u> <u class=ulw>D’abord,</u> <u class=ulw>il</u> <u class=ulw>rappelle</u> <u class=ulw>que</u></span> la réponse négative des Occidentaux justifiait la domination. <span k=7F2A4C><u class=ulw>Autrement</u> <u class=ulw>dit,</u></span> refuser la philosophie aux Noirs revenait à leur refuser l’humanité ; <span k=7F2A4C><u class=ulw>l’expression</u></span> « l’attribut essentiel et indispensable d’une humanité véritable » <span k=7F2A4C><u class=ulw>le</u> <u class=ulw>montre.</u> <u class=ulw>Ensuite,</u> <u class=ulw>il</u> <u class=ulw>établit</u> <u class=ulw>que</u></span> les penseurs africains reprennent la question pour y répondre « positivement ». <span k=7F2A4C><u class=ulw>C’est-à-dire</u> <u class=ulw>que</u></span> prouver une philosophie propre fonde le droit à l’autonomie culturelle et politique ; <span k=7F2A4C><u class=ulw>le</u> <u class=ulw>passage</u></span> « ruiner par là un argument essentiel de l’idéologie impérialiste » <span k=7F2A4C><u class=ulw>l’atteste.</u></span></div></div><div class=\"cpar trans\"><span class=cplab kb=954024>T1</span><div class=cptxt><span k=7F2A4C><u class=ulw>Au</u> <u class=ulw>regard</u> <u class=ulw>de</u> <u class=ulw>ce</u> <u class=ulw>qui</u> <u class=ulw>précède,</u> <u class=ulw>il</u> <u class=ulw>ressort</u> <u class=ulw>que</u> <u class=ulw>pour</u> <u class=ulw>Towa,</u></span> la reconnaissance de l’humanité des Noirs passait par la preuve de leur philosophie. <span k=7F2A4C><u class=ulw>Cette</u> <u class=ulw>perspective</u> <u class=ulw>laisse</u> <u class=ulw>pourtant</u> <u class=ulw>dans</u> <u class=ulw>l’ombre</u></span> le fait que la dignité humaine ne se mérite pas.</div></div><div class=cpar><span class=cplab kb=954024>RT</span><div class=cptxt><span k=7F2A4C><u class=ulw>En</u> <u class=ulw>effet,</u> <u class=ulw>en</u> <u class=ulw>faisant</u> <u class=ulw>de</u> <u class=ulw>la</u> <u class=ulw>philosophie</u> <u class=ulw>la</u> <u class=ulw>preuve</u> <u class=ulw>de</u> <u class=ulw>l’humanité,</u> <u class=ulw>Towa</u> <u class=ulw>donne</u> <u class=ulw>l’impression</u> <u class=ulw>que</u></span> la dignité d’un peuple dépendrait de ses productions intellectuelles. <span k=7F2A4C><u class=ulw>Or</u></span> la dignité appartient à tout être humain du seul fait qu’il est une personne, quoi qu’il produise. Accepter le débat sur ce terrain, c’est déjà reconnaître à l’autre le droit de nous juger. <span k=7F2A4C><u class=ulw>C’est</u> <u class=ulw>ce</u> <u class=ulw>que</u> <u class=ulw>rappelle</u></span> Kant <span k=7F2A4C><u class=ulw>lorsqu’il</u> <u class=ulw>écrit</u> <u class=ulw>que</u></span> « ce qui est supérieur à tout prix, ce qui par suite n’admet pas d’équivalent, c’est ce qui a une dignité ».</div></div><div class=\"cpar trans\"><span class=cplab kb=954024>T2</span><div class=cptxt><span k=7F2A4C><u class=ulw>À</u> <u class=ulw>partir</u> <u class=ulw>de</u> <u class=ulw>là,</u> <u class=ulw>on</u> <u class=ulw>peut</u> <u class=ulw>dire</u> <u class=ulw>que</u></span> Towa risque de suspendre la dignité des Noirs à un verdict extérieur. <span k=7F2A4C><u class=ulw>Toutefois,</u> <u class=ulw>en</u> <u class=ulw>dévoilant</u> <u class=ulw>l’enjeu</u> <u class=ulw>politique</u> <u class=ulw>de</u> <u class=ulw>la</u> <u class=ulw>question,</u> <u class=ulw>ne</u> <u class=ulw>nous</u> <u class=ulw>apprend-il</u> <u class=ulw>pas</u> <u class=ulw>que</u></span> penser par soi-même est déjà un acte de libération ?</div></div><div class=cpar><span class=cplab kb=954024>RIT</span><div class=cptxt><span k=7F2A4C><u class=ulw>Ce</u> <u class=ulw>texte</u> <u class=ulw>de</u> <u class=ulw>Towa,</u> <u class=ulw>au-delà</u> <u class=ulw>de</u> <u class=ulw>ses</u> <u class=ulw>limites,</u> <u class=ulw>est</u> <u class=ulw>remarquable</u> <u class=ulw>et</u> <u class=ulw>actuel</u> <u class=ulw>en</u> <u class=ulw>ce</u> <u class=ulw>sens</u> <u class=ulw>qu’il</u></span> relie la pensée à la libération. <span k=7F2A4C><u class=ulw>En</u> <u class=ulw>montrant</u> <u class=ulw>que</u></span> la négation de la philosophie africaine servait la domination, il invite les Africains à conquérir leur autonomie aussi sur le terrain de la pensée. <span k=7F2A4C><u class=ulw>Aujourd’hui</u> <u class=ulw>encore,</u></span> le débat sur la restitution des œuvres d’art africaines montre que la lutte pour la reconnaissance continue. <span k=7F2A4C><u class=ulw>Son</u> <u class=ulw>héritier</u></span> Paulin Hountondji <span k=7F2A4C><u class=ulw>prolonge</u> <u class=ulw>cette</u> <u class=ulw>exigence</u> <u class=ulw>lorsqu’il</u> <u class=ulw>définit</u> <u class=ulw>la</u> <u class=ulw>philosophie</u> <u class=ulw>africaine</u> <u class=ulw>comme</u></span> « l’ensemble des textes écrits par des Africains eux-mêmes et qualifiés par leurs auteurs eux-mêmes de philosophiques » : <span k=7F2A4C><u class=ulw>c’est</u> <u class=ulw>en</u> <u class=ulw>pensant,</u> <u class=ulw>et</u> <u class=ulw>non</u> <u class=ulw>en</u> <u class=ulw>exhibant</u> <u class=ulw>un</u> <u class=ulw>héritage,</u> <u class=ulw>que</u> <u class=ulw>l’Afrique</u> <u class=ulw>se</u> <u class=ulw>fait</u> <u class=ulw>reconnaître.</u></span></div></div><div class=saute k=954024><i class=fa>&#xF338;</i> tu sautes deux lignes avant la conclusion</div><div class=cpar><span class=cplab kb=954024>C</span><div class=cptxt><span k=7F2A4C><u class=ulw>En</u> <u class=ulw>définitive,</u> <u class=ulw>ce</u> <u class=ulw>texte</u> <u class=ulw>nous</u> <u class=ulw>a</u> <u class=ulw>permis</u> <u class=ulw>de</u> <u class=ulw>cerner</u></span> la portée politique de la question de la philosophie africaine. <span k=7F2A4C><u class=ulw>Si</u> <u class=ulw>au</u> <u class=ulw>cours</u> <u class=ulw>de</u> <u class=ulw>notre</u> <u class=ulw>évaluation</u> <u class=ulw>nous</u> <u class=ulw>avons</u> <u class=ulw>montré</u> <u class=ulw>qu’il</u> <u class=ulw>est</u> <u class=ulw>contestable</u> <u class=ulw>au</u> <u class=ulw>regard</u> <u class=ulw>de</u></span> la dignité humaine, qui ne dépend d’aucun certificat, <span k=7F2A4C><u class=ulw>nous</u> <u class=ulw>avons</u> <u class=ulw>néanmoins</u> <u class=ulw>reconnu</u> <u class=ulw>qu’il</u> <u class=ulw>est</u> <u class=ulw>remarquable</u> <u class=ulw>en</u> <u class=ulw>ceci</u> <u class=ulw>qu’il</u></span> fait de la pensée une arme de libération. <span k=7F2A4C><u class=ulw>Ce</u> <u class=ulw>texte</u> <u class=ulw>présente</u> <u class=ulw>alors</u> <u class=ulw>un</u> <u class=ulw>intérêt</u> <u class=ulw>philosophique</u> <u class=ulw>dans</u> <u class=ulw>une</u> <u class=ulw>perspective</u></span> politique <span k=7F2A4C><u class=ulw>car</u> <u class=ulw>l’auteur</u> <u class=ulw>parle</u> <u class=ulw>de</u></span> l’autonomie culturelle et politique d’un peuple dominé.</div></div></div><p><a id=L-exo_1_2></a></p><div class=exo><span class=exob kb=BF542E><i class=fa>&#xF0A4;</i> 1.2</span><div class=exot>Fais de ce texte un commentaire philosophique. « L’ethnophilosophie, une voie de facilité»</div></div><div class=texte style=border-top-color:#C59687><span class=quo k=CFA99C><i class=fa>&#xF10D;</i></span><p>L’ethno-philosophie telle qu’elle s’est pratiquée jusqu’ici n’a trop souvent été qu’une voie de facilité, faisant l’économie à la fois des techniques et des méthodes d’enquête ethnologiques et de la discussion philosophique des idées et des valeurs mises en avant, et tout ceci, au nom de l’africanité. En plus des multiples impasses théoriques auxquelles elle aboutit, l’ethno-philosophie s’est avérée d’une grande stérilité. En se soustrayant aux exigences scientifiques d’enquête, elle se met hors d’état d’enrichir notre connaissance de nous-mêmes par l’apport de documents neufs solidement établis ; et en esquivant le débat philosophique sur les idées et les valeurs, il ne lui reste pour les imposer que la voie d’un dogmatisme desséchant dans lequel la négritude entendue comme retour à nos sources culturelles dans la fierté retrouvée, est pervertie au point de n’être plus qu’un avatar du « magister dixit ». En raison d’un tel dogmatisme, les idées avancées par l’ethnophilosophie sont figées dès leur mise au jour et ne sont susceptibles d’aucun développement.</p><div class=source>— Marcien Towa, <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, CLÉ, Yaoundé, 1971, pp. 32-33.</div></div><div class=\"box orientation tagged\" kb=F5E3DE><span class=tag kb=954024><i class=fa>&#xF14E;</i> ORIENTATION</span><p><span k=8A3C22><b> </b></span><b>Thème : </b>l’ethnophilosophie. <b>Problème : </b>la valeur de l’ethnophilosophie comme savoir et comme philosophie. <b>Thèse : </b>c’est une voie de facilité, stérile et dogmatique, qui évite l’enquête rigoureuse et la discussion des idées.</p></div><div class=stacktab><div class=sth kb=BF522E>Étape / Pistes (à approfondir)</div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><span k=8A3C22><b>EA — Deux articulations</b></span></div><div class=srb><p><span k=C0532F><b>1 </b></span>Towa accuse ce courant de se dispenser du travail de terrain et du débat d’idées, en se réfugiant derrière l’« africanité » (indice : « voie de facilité »).<hr class=isep><span k=C0532F><b>2 </b></span>Il en conclut que l’ethnophilosophie produit peu de savoir neuf et fige ses convictions dans un « magister dixit » (indice : « dogmatisme desséchant »).</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RT — Pistes de réfutation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Tempels, Kagame : </b>ils ont mis au jour un système de pensée africain : pour Tempels, la force vitale est au centre de la « philosophie bantoue » ; pour Kagame, la langue dévoile la <i>philosophie bantu-rwandaise de l’être</i>.<hr class=isep><span k=C0532F><b>2 </b></span><b>Senghor : </b>« L’émotion est nègre comme la raison est hellène » ; la négritude redonne fierté et enracinement aux peuples colonisés.<hr class=isep><span k=C0532F><b>3 </b></span><b>Hampâté Bâ : </b>« En Afrique, quand un vieillard meurt, c’est une bibliothèque qui brûle » ; la tradition orale est une mémoire vivante, source de savoir.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RIT — Pistes de réinterprétation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Hountondji : </b>il dénonce l’« unanimisme » et demande d’étudier les « savoirs endogènes » avec rigueur : on peut travailler sur les traditions sans les confondre avec la philosophie.<hr class=isep><span k=C0532F><b>2 </b></span><b>Wiredu : </b>il plaide pour une « décolonisation conceptuelle » : soumettre les concepts de la pensée akan à l’analyse critique, sans tomber dans le dogmatisme.<hr class=isep><span k=C0532F><b>3 </b></span>Les proverbes, contes et mythes servent de matière à la réflexion, à condition de les discuter.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>C — Intérêt (une perspective)</b></div><div class=srb><p><b>Méthodologique</b>, car l’auteur parle des exigences d’une recherche rigoureuse : enquête, méthode et discussion critique.</p></div></div></div><p><a id=L-exo_1_3></a></p><div class=exo><span class=exob kb=BF542E><i class=fa>&#xF0A4;</i> 1.3</span><div class=exot>Fais de ce texte un commentaire philosophique. « Philosopher aujourd’hui, c’est penser notre situation actuelle»</div></div><div class=texte style=border-top-color:#C59687><span class=quo k=CFA99C><i class=fa>&#xF10D;</i></span><p>Pour ouvrir la voie à un développement philosophique en Afrique, il faut que, résolument, nous nous détournions de l’ethnophilosophie, aussi bien de sa problématique que de ses méthodes. Plutôt que l’exhumation d’une philosophie africaine originale selon des voies qui ne se soumettent ni aux exigences de la science ni à celles de la philosophie, notre dessein principal devrait être de parvenir à une saisie et à une expression philosophiques de notre « être-dans-le-monde » actuel et à une détermination de la manière de le prendre en charge et de l’infléchir dans une direction définie. Une philosophie africaine originale arrachée à la nuit du passé n’a pu être, si elle a existé, que l’expression d’une situation elle-même passée. C’est dire que la redécouverte d’une telle philosophie ne saurait résoudre notre problème philosophique actuel, savoir, l’effort d’élucidation de notre actuel rapport au monde. Notre monde n’étant plus celui de nos ancêtres — il s’en faut de beaucoup — leur conception du monde ne saurait non plus être la nôtre.</p><div class=source>— Marcien Towa, <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, CLÉ, Yaoundé, 1971, p. 35.</div></div><div class=\"box orientation tagged\" kb=F5E3DE><span class=tag kb=954024><i class=fa>&#xF14E;</i> ORIENTATION</span><p><span k=8A3C22><b> </b></span><b>Thème : </b>la tâche de la philosophie en Afrique. <b>Problème : </b>le choix entre déterrer un passé et penser le présent comme tâche de la philosophie africaine. <b>Thèse : </b>il faut quitter l’ethnophilosophie et élucider notre être-dans-le-monde actuel, car le monde de nos ancêtres n’est plus le nôtre.</p></div><div class=stacktab><div class=sth kb=BF522E>Étape / Pistes (à approfondir)</div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><span k=8A3C22><b>EA — Deux articulations</b></span></div><div class=srb><p><span k=C0532F><b>1 </b></span>Towa invite à se détourner de l’ethnophilosophie, de sa problématique comme de ses méthodes, pour saisir et exprimer notre « être-dans-le-monde » actuel et la manière de l’infléchir.<hr class=isep><span k=C0532F><b>2 </b></span>Il justifie ce choix : une philosophie du passé exprime une situation passée ; la redécouvrir ne résout pas nos problèmes (indice : « notre monde n’étant plus celui de nos ancêtres »).</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RT — Pistes de réfutation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Cheikh Anta Diop : </b>« le retour à l’Égypte […] est la condition nécessaire pour réconcilier les civilisations africaines avec l’histoire » ; le passé fonde l’identité et éclaire l’action.<hr class=isep><span k=C0532F><b>2 </b></span><b>Gadamer : </b>« L’histoire ne nous appartient pas, c’est nous qui lui appartenons » ; on ne comprend le présent qu’à partir d’un héritage qu’on interprète.<hr class=isep><span k=C0532F><b>3 </b></span><b>Cabral : </b>la libération nationale est un « acte de culture » : s’enraciner dans son histoire donne la force de lutter.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RIT — Pistes de réinterprétation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Hountondji : </b>la philosophie africaine vaut comme discours critique sur les problèmes actuels du continent (éducation, science, développement), contre l’« extraversion » du savoir.<hr class=isep><span k=C0532F><b>2 </b></span><b>Eboussi Boulaga : </b><i>La Crise du Muntu </i>(sous-titre : <i>Authenticité africaine et philosophie</i>) prolonge cette exigence : penser l’impasse actuelle de l’Africain plutôt que célébrer une authenticité figée.<hr class=isep><span k=C0532F><b>3 </b></span><b>Mbembe : </b><i>Sortir de la grande nuit </i>invite à penser l’Afrique d’aujourd’hui (jeunesse, numérique, mobilité) hors des clichés du passé.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>C — Intérêt (une perspective)</b></div><div class=srb><p><b>Idéologique</b>, car l’auteur parle d’une philosophie tournée vers notre « être-dans-le-monde » actuel plutôt que vers le passé.</p></div></div></div><p><a id=L-exo_1_4></a></p><div class=exo><span class=exob kb=BF542E><i class=fa>&#xF0A4;</i> 1.4</span><div class=exot>Fais de ce texte un commentaire philosophique. « Le désir de spécificité précède la dilution»</div></div><div class=texte style=border-top-color:#C59687><span class=quo k=CFA99C><i class=fa>&#xF10D;</i></span><p>L’affirmation que la philosophie négro-africaine diffère radicalement de celle de l’Europe n’est une conclusion qu’en apparence. Tout comme l’assertion qu’il existe une philosophie négro-africaine, elle est déjà impliquée dans la nécessité où l’on s’est trouvé d’élargir le concept de philosophie de manière à le rendre coextensif à toute forme culturelle indistinctement. S’ils avaient pu exhiber une philosophie négro-africaine semblable à celle de l’Europe, nos auteurs n’auraient eu aucun besoin de diluer préalablement le concept de philosophie dans celui de culture. En réalité, la volonté de présenter comme philosophie des modes de pensée considérés comme spécifiquement africains, précède et explique la dilution de la philosophie dans la culture, et non l’inverse.</p><div class=source>— Marcien Towa, <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, CLÉ, Yaoundé, 1971, pp. 28-29.</div></div><div class=\"box orientation tagged\" kb=F5E3DE><span class=tag kb=954024><i class=fa>&#xF14E;</i> ORIENTATION</span><p><span k=8A3C22><b> </b></span><b>Thème : </b>la genèse de l’ethnophilosophie. <b>Problème : </b>l’origine de la différence africaine : découverte de la recherche ou point de départ posé d’avance. <b>Thèse : </b>le désir de spécificité précède et explique la dilution de la philosophie dans la culture, et non l’inverse.</p></div><div class=stacktab><div class=sth kb=BF522E>Étape / Pistes (à approfondir)</div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><span k=8A3C22><b>EA — Deux articulations</b></span></div><div class=srb><p><span k=C0532F><b>1 </b></span>Towa conteste que la différence avec l’Europe soit une conclusion de recherche : elle est déjà impliquée dans l’élargissement du concept de philosophie à toute forme culturelle.<hr class=isep><span k=C0532F><b>2 </b></span>Il raisonne par l’absurde : si l’on avait pu montrer une philosophie africaine semblable à l’européenne, on n’aurait pas eu besoin de diluer le concept ; c’est donc la volonté de spécificité qui explique la dilution.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RT — Pistes de réfutation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Wittgenstein : </b>« la signification d’un mot est son usage dans le langage » ; élargir un concept n’est pas forcément une ruse, les mots évoluent.<hr class=isep><span k=C0532F><b>2 </b></span><b>Kagame : </b>il part de la langue (le kinyarwanda) et de ses catégories, comme le dit le titre de son livre, <i>La philosophie bantu-rwandaise de l’être </i>; sa démarche n’est pas seulement guidée par un désir de différence.<hr class=isep><span k=C0532F><b>3 </b></span><b>Popper : </b>comment une idée naît relève de la psychologie ; seule sa mise à l’épreuve logique compte : l’origine d’une thèse ne dit rien de sa vérité.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RIT — Pistes de réinterprétation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Hountondji : </b>il distingue la philosophie, discours critique, de la simple culture : on peut étudier les cultures sans les confondre avec la philosophie.<hr class=isep><span k=C0532F><b>2 </b></span><b>Bachir Diagne : </b><i>L’encre des savants </i>montre une tradition écrite africaine (manuscrits de Tombouctou) où l’on discute et argumente : la philosophie existe sans être diluée dans la culture.<hr class=isep><span k=C0532F><b>3 </b></span>Aujourd’hui, les cursus de philosophie des universités africaines séparent l’étude des cultures et la pratique de l’argumentation.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>C — Intérêt (une perspective)</b></div><div class=srb><p><b>Méthodologique</b>, car l’auteur parle de la confusion entre culture et philosophie et de la manière de les distinguer.</p></div></div></div><p><a id=L-exo_1_5></a></p><div class=exo><span class=exob kb=BF542E><i class=fa>&#xF0A4;</i> 1.5</span><div class=exot>Fais de ce texte un commentaire philosophique. « L’ethnophilosophie trahit l’ethnologie et la philosophie»</div></div><div class=texte style=border-top-color:#C59687><span class=quo k=CFA99C><i class=fa>&#xF10D;</i></span><p>L’ethno-philosophie expose objectivement les croyances, les mythes, les rituels, puis brusquement, cet exposé objectif se mue en profession de foi métaphysique, sans se soucier ni de réfuter la philosophie occidentale, ni de fonder en raison son adhésion à la pensée africaine. De la sorte l’ethnophilosophie trahit à la fois l’ethnologie et la philosophie. L’ethnologue décrit, expose, explique, mais ne s’engage pas (du moins pas ouvertement) quant au bien-fondé de ce qui est ainsi décrit, expliqué. Elle trahit aussi la philosophie parce que la pierre de touche qui lui permet d’opérer un choix entre les diverses opinions est avant tout l’appartenance ou la non-appartenance à la tradition africaine, alors qu’un exposé philosophique est toujours une argumentation, une démonstration ou une réfutation. Ce qu’un philosophe retient et propose est toujours, du moins en droit, la conclusion d’un débat contradictoire, c’est-à-dire d’un examen critique et absolument libre.</p><div class=source>— Marcien Towa, <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, CLÉ, Yaoundé, 1971, p. 31.</div></div><div class=\"box orientation tagged\" kb=F5E3DE><span class=tag kb=954024><i class=fa>&#xF14E;</i> ORIENTATION</span><p><span k=8A3C22><b> </b></span><b>Thème : </b>l’ethnophilosophie entre ethnologie et philosophie. <b>Problème : </b>le statut de l’ethnophilosophie. <b>Thèse : </b>elle trahit l’ethnologie et la philosophie : elle mêle description et profession de foi, et juge selon l’appartenance à la tradition plutôt que par l’argument.</p></div><div class=stacktab><div class=sth kb=BF522E>Étape / Pistes (à approfondir)</div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><span k=8A3C22><b>EA — Deux articulations</b></span></div><div class=srb><p><span k=C0532F><b>1 </b></span>Towa montre que l’ethnophilosophie expose d’abord objectivement croyances et rituels, puis bascule en profession de foi métaphysique sans réfuter l’Occident ni fonder son adhésion.<hr class=isep><span k=C0532F><b>2 </b></span>Il oppose l’ethnologue, qui décrit sans s’engager, au philosophe, qui argumente, démontre et réfute : sa conclusion est celle d’un débat contradictoire, libre et critique.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RT — Pistes de réfutation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Gadamer : </b>« L’histoire ne nous appartient pas, c’est nous qui lui appartenons » ; toute pensée s’enracine dans une tradition sans être dogmatique pour autant.<hr class=isep><span k=C0532F><b>2 </b></span><b>Kagame : </b>son travail s’appuie sur l’analyse de la langue et de ses catégories : il fournit une méthode, non une simple profession de foi.<hr class=isep><span k=C0532F><b>3 </b></span><b>Sartre : </b>« Chaque parole a des retentissements. Chaque silence aussi » (<i>Qu’est-ce que la littérature ?</i>) : aucun discours n’est neutre, le penseur est toujours engagé.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>RIT — Pistes de réinterprétation (tu n’en retiens qu’une)</b></div><div class=srb><p><span k=C0532F><b>1 </b></span><b>Hountondji : </b>il sépare l’exposé des croyances et l’argumentation philosophique : la méthode de Towa devient une règle de travail.<hr class=isep><span k=C0532F><b>2 </b></span><b>Bidima : </b><i>La palabre </i>montre que la tradition africaine connaît le débat contradictoire : l’idéal de Towa existe déjà dans nos pratiques.<hr class=isep><span k=C0532F><b>3 </b></span>À l’école, on apprend à distinguer ce qu’on croit, ce qu’on décrit et ce qu’on démontre.</p></div></div><div class=stackrow><div class=srh style=color:#954024;border-bottom-color:#DABCB2><b>C — Intérêt (une perspective)</b></div><div class=srb><p><b>Méthodologique</b>, car l’auteur parle de la différence entre décrire des croyances, y adhérer et argumenter.</p></div></div></div><div class=\"box notebox tagged\" kb=E8F5F2><span class=tag kb=1F8078>POUR T’ENTRAÎNER SEUL · DEUX AUTRES TEXTES</span><p>Retrouve ces passages dans l’œuvre, recopie-les, puis commente-les seul en suivant la méthode ; vérifie tes pistes avec la fiche du chapitre.</p><p><b>Texte 1.6</b> — <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, p. 26. <b>Début :</b> « Mais comment établir l’existence d’une philosophie africaine originale ? » <b>Fin :</b> « …mythe, religion, poésie, art, science, etc. » <i>Piste : la méthode de l’ethnophilosophie : élargir le concept de philosophie jusqu’à celui de culture.</i></p><p><b>Texte 1.7</b> — <i>Essai sur la problématique philosophique dans l’Afrique actuelle</i>, p. 75 (conclusion). <b>Début :</b> « Les recherches de ce genre présentent, nous en convenons, un intérêt certain. » <b>Fin :</b> « …de notre présente condition dans le monde. » <i>Piste : l’histoire de notre pensée ne doit pas nous dispenser de philosopher.</i></p></div>","libre":true},{"id":"s5","kind":"chap","num":"2","titre":"Négritude, assimilation et libération","sous":"Marcien Towa · Essai sur la problématique philosophique dans l’Afrique actuelle","couleur":"B8781F","genre":"Chapitre","html":""},{"id":"s6","kind":"chap","num":"3","titre":"Révolution, puissance et affirmation de soi","sous":"Marcien Towa · Essai sur la problématique philosophique dans l’Afrique actuelle","couleur":"6B4C9C","genre":"Chapitre","html":""},{"id":"s7","kind":"chap","num":"4","titre":"Philosophie, science et raison","sous":"Marcien Towa · Essai sur la problématique philosophique dans l’Afrique actuelle","couleur":"2E7D4F","genre":"Chapitre","html":""},{"id":"s8","kind":"chap","num":"5","titre":"Philosophie, religion et pensée critique","sous":"Marcien Towa · Essai sur la problématique philosophique dans l’Afrique actuelle","couleur":"B03B6B","genre":"Chapitre","html":""},{"id":"s9","kind":"chap","num":"6","titre":"La liberté","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"1C6B96","genre":"Chapitre","html":""},{"id":"s10","kind":"chap","num":"7","titre":"Avoir, être et développement","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"1F8078","genre":"Chapitre","html":""},{"id":"s11","kind":"chap","num":"8","titre":"Bien-être, bonheur et accomplissement de soi","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"BF522E","genre":"Chapitre","html":""},{"id":"s12","kind":"chap","num":"9","titre":"Médiocrité et excellence","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"B8781F","genre":"Chapitre","html":""},{"id":"s13","kind":"chap","num":"10","titre":"Culture, tradition et modernité","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"6B4C9C","genre":"Chapitre","html":""},{"id":"s14","kind":"chap","num":"11","titre":"Religion, spiritualité et morale","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"2E7D4F","genre":"Chapitre","html":""},{"id":"s15","kind":"chap","num":"12","titre":"L’art et l’artiste","sous":"Ebénézer Njoh-Mouelle · De la médiocrité à l’excellence","couleur":"B03B6B","genre":"Chapitre","html":""},{"id":"s16","kind":"part","num":"","titre":"Troisième partie — La dissertation","sous":"","couleur":"1F2230","genre":"","html":""},{"id":"s17","kind":"chap","num":"13","titre":"Deux périodes de l’histoire de la philosophie","sous":"Leçons 1 et 2 de la progression : les sources de la connaissance, la foi et la raison.","couleur":"BF522E","genre":"Chapitre","html":""},{"id":"s18","kind":"chap","num":"14","titre":"L’argumentation","sous":"Leçons 9 et 10 de la progression.","couleur":"B8781F","genre":"Chapitre","html":""},{"id":"s19","kind":"chap","num":"15","titre":"La démonstration et la méthode","sous":"Leçons 11 et 12 de la progression.","couleur":"6B4C9C","genre":"Chapitre","html":""},{"id":"s20","kind":"chap","num":"16","titre":"Passion et raison","sous":"Leçons 15 et 16 de la progression.","couleur":"2E7D4F","genre":"Chapitre","html":"<div class=chapbanner kb=2E7D4F><div class=chnum kb=205837><span>CHAPITRE</span><b>16</b></div><div class=chtxt><div class=chtitle>Passion et raison</div><div class=chsub>Leçons 15 et 16 de la progression.</div></div></div><p><a id=L-chap_CHAPITRE-16></a></p><div class=ornament style=--o:#84A492><i></i><b></b><i></i></div><div class=hprob kb=24623E><span class=hnum>16.1</span> PROBLÈME 1 : LA VALEUR DES PASSIONS</div><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF084;</i></span></span><div><span k=205A39><b>Concepts clés : passion </b></span>= penchant très fort et durable qui domine la personne; <span k=205A39><b>émotion </b></span>= réaction brève (peur, colère); <span k=205A39><b>raison </b></span>= faculté de juger et de se maîtriser.</div></div><hr class=sepparts style=border-color:#6E947E><div class=theselabel style=background:#DEEBE3;color:#205A39><i class=fa>&#xF0DA;</i> <b>THÈSE 1 : LES PASSIONS ONT UNE VALEUR POSITIVE</b></div><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=2D7D4F><b></b></span>Pour Hegel, les passions sont le moteur de l’histoire : les grandes actions naissent de passions fortes, et la raison s’en sert pour atteindre ses buts (la « ruse de la raison »).</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Animé par la passion de la justice, Nelson Mandela lutte pendant des années contre l’apartheid.</div></div><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=2D7D4F><b></b></span>Pour Diderot, seules les grandes passions élèvent l’âme aux grandes choses : artistes, savants et héros sont portés par elles.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un musicien passionné joue des heures chaque jour et finit par créer de belles œuvres.</div></div><h5 class=hthree k=205A39><span class=hico><i class=fa>&#xF0C0;</i></span>Auteurs clés</h5><div class=\"box citebox\" kb=EDF2F0><p><span k=205A39><b>Hegel </b></span>: « Rien de grand ne s’est accompli dans le monde sans passion. »</p></div><div class=\"box citebox\" kb=EDF2F0><p>Descartes pense que les passions sont « bonnes de leur nature » : elles nous poussent vers ce qui est utile.</p></div><ul class=puces><li><span class=pu k=24623E><i class=fa>&#xF111;</i></span><div><span k=205A39><b>Limite : </b></span><i>une passion sans contrôle peut devenir dangereuse (voir thèse 2).</i></div></li></ul><hr class=sepparts style=border-color:#6E947E><div class=theselabel style=background:#DEEBE3;color:#205A39><i class=fa>&#xF0DA;</i> <b>THÈSE 2 : LES PASSIONS ONT UNE VALEUR NÉGATIVE</b></div><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=2D7D4F><b></b></span>Pour Spinoza, l’homme dominé par ses passions vit dans la « servitude » : il croit être libre alors qu’il est conduit par ce qu’il subit.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un joueur d’argent sait qu’il perd tout et continue de jouer : il n’est plus libre.</div></div><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=2D7D4F><b></b></span>Pour Kant, la passion est plus grave que l’émotion : l’émotion passe vite, la passion s’installe et ferme l’esprit à la raison.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un homme très jaloux, aveuglé par la colère, fait du mal à quelqu’un et le regrette ensuite.</div></div><h5 class=hthree k=205A39><span class=hico><i class=fa>&#xF0C0;</i></span>Auteurs clés</h5><div class=\"box citebox\" kb=EDF2F0><p>Kant compare les passions à des « cancers » qui rongent la raison.</p></div><div class=\"box citebox\" kb=EDF2F0><p>Les stoïciens (Épictète, Marc Aurèle) veulent se libérer des passions pour trouver la paix de l’âme.</p></div><ul class=puces><li><span class=pu k=24623E><i class=fa>&#xF111;</i></span><div><span k=205A39><b>Limite : </b></span><i>supprimer toutes les passions est impossible et appauvrirait la vie.</i></div></li></ul><hr class=sepparts style=border-color:#6E947E><p><span k=205A39><b>SYNTHÈSE</b></span></p><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=2D7D4F><b></b></span>Pour Aristote, la vertu est un « juste milieu » : la raison règle les passions sans les supprimer.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Le courage se trouve entre la peur excessive et la témérité.</div></div><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=2D7D4F><b></b></span>Pour Descartes, il ne faut pas fuir les passions mais en éviter les excès et les mauvais usages, en les guidant par la raison.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Aimer le football donne de la joie ; se battre avec les supporters adverses est un excès.</div></div><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF140;</i></span></span><div><span k=205A39><b>Conclusion : </b></span>les passions ne sont ni bonnes ni mauvaises par nature : leur valeur dépend de l’usage qu’on en fait et du contrôle qu’on garde sur elles.</div></div><div class=ornament style=--o:#84A492><i></i><b></b><i></i></div><div class=hprob kb=24623E><span class=hnum>16.2</span> PROBLÈME 2 : LE RAPPORT ENTRE PASSION ET RAISON</div><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF084;</i></span></span><div><span k=205A39><b>Concepts clés : raison </b></span>= faculté de réfléchir et de juger; <span k=205A39><b>passion </b></span>= penchant fort qui pousse à agir; <span k=205A39><b>maîtrise de soi </b></span>= volonté guidée par la raison.</div></div><hr class=sepparts style=border-color:#6E947E><div class=theselabel style=background:#DEEBE3;color:#205A39><i class=fa>&#xF0DA;</i> <b>THÈSE 1 : PASSION ET RAISON PEUVENT ÊTRE OPPOSÉES</b></div><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=2D7D4F><b></b></span>Pour Platon, la raison doit diriger les passions, comme un cavalier dirige son cheval : s’il lâche les rênes, le cheval part dans tous les sens.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un élève veut regarder un match (passion), mais doit réviser pour son examen (raison) : il est tiraillé.</div></div><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=2D7D4F><b></b></span>Pour les stoïciens, la passion est un faux jugement qui trouble l’esprit : le sage doit s’en libérer grâce à la raison.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Une personne aveuglée par l’amour ne voit pas que l’autre lui ment.</div></div><h5 class=hthree k=205A39><span class=hico><i class=fa>&#xF0C0;</i></span>Auteurs clés</h5><div class=\"box citebox\" kb=EDF2F0><p><span k=205A39><b>Épictète </b></span>: « Ce ne sont pas les choses qui troublent les hommes, mais les jugements qu’ils portent sur elles. »</p></div><div class=\"box citebox\" kb=EDF2F0><p>Kant pense que la passion s’oppose à la liberté, car elle ne laisse plus la raison choisir.</p></div><ul class=puces><li><span class=pu k=24623E><i class=fa>&#xF111;</i></span><div><span k=205A39><b>Limite : </b></span><i>sans aucune passion, l’homme n’agirait presque jamais (voir thèse 2).</i></div></li></ul><hr class=sepparts style=border-color:#6E947E><div class=theselabel style=background:#DEEBE3;color:#205A39><i class=fa>&#xF0DA;</i> <b>THÈSE 2 : PASSION ET RAISON PEUVENT ÊTRE COMPLÉMENTAIRES</b></div><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=2D7D4F><b></b></span>Pour Hume, c’est la passion qui fixe le but ; la raison ne fait que trouver les moyens de l’atteindre.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un sportif passionné suit un entraînement bien pensé pour progresser.</div></div><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=2D7D4F><b></b></span>Pour Spinoza, une passion ne peut être arrêtée que par une passion plus forte ; la raison nous aide à comprendre ce qui est vraiment bon pour nous.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>L’envie de réussir l’examen devient plus forte que l’envie de jouer : l’élève révise.</div></div><h5 class=hthree k=205A39><span class=hico><i class=fa>&#xF0C0;</i></span>Auteurs clés</h5><div class=\"box citebox\" kb=EDF2F0><p><span k=205A39><b>Hume </b></span>: « La raison est, et ne doit être, que l’esclave des passions. »</p></div><div class=\"box citebox\" kb=EDF2F0><p>Pour Rousseau, nos passions sont les principaux instruments de notre conservation.</p></div><ul class=puces><li><span class=pu k=24623E><i class=fa>&#xF111;</i></span><div><span k=205A39><b>Limite : </b></span><i>si la raison n’est que l’esclave des passions, comment peut-elle encore les juger ou les corriger ?</i></div></li></ul><hr class=sepparts style=border-color:#6E947E><p><span k=205A39><b>SYNTHÈSE</b></span></p><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=2D7D4F><b></b></span>Pour Descartes, la volonté éclairée par la raison peut maîtriser les passions sans les supprimer : c’est la maîtrise de soi.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un élève en colère après une mauvaise note réfléchit, puis décide de mieux réviser au lieu de tout abandonner.</div></div><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=2D7D4F><b></b></span>Pour Hegel, la raison se sert des passions des hommes pour réaliser de grandes choses : les deux travaillent ensemble.</div></li></ul><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF0EB;</i></span></span><div><span k=205A39><b>Exemple : </b></span>Un chercheur passionné par son travail réfléchit pendant des années jusqu’à faire une découverte.</div></div><div class=subline><span class=sl><span k=2D7D4F><i class=fa>&#xF140;</i></span></span><div><span k=205A39><b>Conclusion : </b></span>passion et raison ne sont pas ennemies par nature : sans la raison, la passion est aveugle ; sans la passion, la raison manque de force.</div></div><h3 class=hone k=2D7D4F><span class=hico><i class=fa>&#xF303;</i></span><span class=hnum>16.3</span> Un devoir entièrement rédigé, sur copie à grands carreaux</h3><div class=\"box callout tagged\" kb=FFF5DA><span class=tag kb=2E7D4F>SUJET</span><p><b>Sujet : </b>Les passions sont-elles un danger pour l’homme ? <span k=5F6472>(sujet-question)</span></p></div><div class=badgewrap><span class=badge kb=7A5EB5>DISSERTATION SUR LE CHAPITRE 16 · SUJET-QUESTION</span></div><div class=\"copie f-dev\"><div class=cpar><span class=cplab kb=24623E>INTRO</span><div class=cptxt><span k=205A39><u class=ulw>Hegel</u> <u class=ulw>soutient</u> <u class=ulw>que</u> </span>« rien de grand ne s’est accompli dans le monde sans passion ». <span k=205A39><u class=ulw>Au</u> <u class=ulw>contraire,</u> </span>Kant <span k=205A39><u class=ulw>compare</u> </span>les passions à des « cancers » qui rongent la raison. <span k=205A39><u class=ulw>Ce</u> <u class=ulw>débat</u> <u class=ulw>nous</u> <u class=ulw>conduit</u> <u class=ulw>à</u> <u class=ulw>nous</u> <u class=ulw>demander</u> <u class=ulw>:</u> </span>les passions sont-elles un danger pour l’homme ? <span k=205A39><u class=ulw>Il</u> <u class=ulw>s’agit</u> <u class=ulw>là</u> <u class=ulw>du</u> <u class=ulw>problème</u> <u class=ulw>de</u> </span>la valeur des passions, <span k=205A39><u class=ulw>qui</u> <u class=ulw>revient</u> <u class=ulw>à</u> <u class=ulw>se</u> <u class=ulw>demander</u> <u class=ulw>si</u> </span>elles sont un obstacle à la raison ou une force qu’il faut éduquer. <span k=205A39><u class=ulw>Faut-il</u> <u class=ulw>alors</u> </span>craindre les passions comme un mal, ou les accueillir comme une énergie ?</div></div><div class=saute k=24623E><i class=fa>&#xF338;</i> tu sautes deux lignes après l’introduction</div><div class=cpar><span class=cplab kb=24623E>THÈSE</span><div class=cptxt><span k=205A39><u class=ulw>Une</u> <u class=ulw>première</u> <u class=ulw>réponse</u> <u class=ulw>s’impose</u> <u class=ulw>:</u> </span>les passions sont un danger pour l’homme. <span k=205A39><u class=ulw>Deux</u> <u class=ulw>raisons</u> <u class=ulw>l’établissent</u> <u class=ulw>:</u> </span>la servitude qu’elles entraînent <span k=205A39><u class=ulw>et</u> <u class=ulw>surtout</u> </span>le mal qu’elles font aux autres et à soi-même.</div></div><div class=cpar><span class=cplab kb=24623E>Arg. 1</span><div class=cptxt><span k=205A39><u class=ulw>Pour</u> <u class=ulw>commencer,</u> </span>les passions asservissent l’homme. Dominé par un désir plus fort que lui, il croit être libre alors qu’il subit. <span k=205A39><u class=ulw>C’est</u> <u class=ulw>le</u> <u class=ulw>cas</u> <u class=ulw>du</u> </span>joueur d’argent qui sait qu’il perd tout et continue de jouer. <span k=205A39><u class=ulw>Spinoza</u> <u class=ulw>a</u> <u class=ulw>pu</u> <u class=ulw>écrire</u> <u class=ulw>que</u> </span>l’homme dominé par ses passions vit dans la « servitude », car il ne se commande plus.</div></div><div class=cpar><span class=cplab kb=24623E>Arg. 2</span><div class=cptxt><span k=205A39><u class=ulw>De</u> <u class=ulw>plus,</u> </span>les passions aveuglent et poussent à la violence. La colère ou la jalousie ôtent à la raison le pouvoir de juger. <span k=205A39><u class=ulw>Par</u> <u class=ulw>exemple,</u> </span>un homme très jaloux, aveuglé par la colère, fait du mal à quelqu’un et le regrette ensuite. <span k=205A39><u class=ulw>Kant</u> <u class=ulw>va</u> <u class=ulw>jusqu’à</u> <u class=ulw>dire</u> <u class=ulw>que</u> </span>les passions sont des « cancers » pour la raison pure pratique.</div></div><div class=\"cpar trans\"><span class=cplab kb=24623E>T1</span><div class=cptxt><span k=205A39><u class=ulw>Ainsi,</u> </span>les passions peuvent apparaître comme un mal : elles asservissent et aveuglent. <span k=205A39><u class=ulw>Or</u> </span>cette condamnation ne retient-elle que leur face sombre ? <span k=205A39><u class=ulw>Ne</u> <u class=ulw>peut-on</u> <u class=ulw>pas</u> </span>y voir aussi la source des grandes réalisations ?</div></div><div class=cpar><span class=cplab kb=24623E>ANTITH.</span><div class=cptxt><span k=205A39><u class=ulw>Une</u> <u class=ulw>autre</u> <u class=ulw>lecture</u> <u class=ulw>est</u> <u class=ulw>pourtant</u> <u class=ulw>possible</u> <u class=ulw>:</u> </span>les passions ne sont pas un danger, mais une force pour l’homme. <span k=205A39><u class=ulw>Deux</u> <u class=ulw>raisons</u> <u class=ulw>l’établissent</u> <u class=ulw>:</u> </span>leur puissance d’action <span k=205A39><u class=ulw>et</u> <u class=ulw>surtout</u> </span>leur rôle dans la création.</div></div><div class=cpar><span class=cplab kb=24623E>Arg. 1</span><div class=cptxt><span k=205A39><u class=ulw>En</u> <u class=ulw>premier</u> <u class=ulw>lieu,</u> </span>les passions donnent à l’homme l’énergie d’entreprendre. Sans désir fort, personne ne persévère dans un effort long et difficile. <span k=205A39><u class=ulw>Animé</u> <u class=ulw>par</u> <u class=ulw>la</u> <u class=ulw>passion</u> <u class=ulw>de</u> <u class=ulw>la</u> <u class=ulw>justice,</u> </span>Nelson Mandela a lutté pendant des années contre l’apartheid. <span k=205A39><u class=ulw>Hegel</u> <u class=ulw>a</u> <u class=ulw>pu</u> <u class=ulw>dire</u> <u class=ulw>que</u> </span>les grandes actions naissent de passions : « Rien de grand ne s’est accompli dans le monde sans passion. »</div></div><div class=cpar><span class=cplab kb=24623E>Arg. 2</span><div class=cptxt><span k=205A39><u class=ulw>En</u> <u class=ulw>outre,</u> </span>les passions élèvent l’âme vers les grandes œuvres. Les artistes et les savants se donnent tout entiers à ce qui les passionne. <span k=205A39><u class=ulw>Ainsi,</u> </span>un musicien passionné joue des heures chaque jour et finit par composer de belles œuvres. <span k=205A39><u class=ulw>Diderot</u> <u class=ulw>affirme</u> <u class=ulw>que</u> </span>seules les grandes passions peuvent élever l’âme aux grandes choses.</div></div><div class=\"cpar trans\"><span class=cplab kb=24623E>T2</span><div class=cptxt><span k=205A39><u class=ulw>Cette</u> <u class=ulw>deuxième</u> <u class=ulw>analyse</u> <u class=ulw>montre</u> <u class=ulw>que</u> </span>les passions sont aussi une énergie nécessaire. <span k=205A39><u class=ulw>Or</u> </span>une passion sans contrôle peut ruiner l’homme. <span k=205A39><u class=ulw>D’où</u> <u class=ulw>la</u> <u class=ulw>nécessité</u> <u class=ulw>de</u> </span>chercher une position qui garde l’énergie des passions tout en évitant leurs ravages.</div></div><div class=cpar><span class=cplab kb=24623E>SYNTH.</span><div class=cptxt><span k=205A39><u class=ulw>Une</u> <u class=ulw>position</u> <u class=ulw>médiane</u> <u class=ulw>s’impose</u> <u class=ulw>:</u> </span>les passions ne sont ni bonnes ni mauvaises par nature : tout dépend de l’usage qu’on en fait. <span k=205A39><u class=ulw>On</u> <u class=ulw>peut</u> <u class=ulw>l’établir</u> <u class=ulw>de</u> <u class=ulw>deux</u> <u class=ulw>manières</u> <u class=ulw>:</u> </span>la maîtrise par la raison et l’éducation des passions.</div></div><div class=cpar><span class=cplab kb=24623E>Arg. 1</span><div class=cptxt><span k=205A39><u class=ulw>D’un</u> <u class=ulw>côté,</u> </span>la raison peut régler les passions sans les supprimer. La vertu consiste à trouver la mesure entre l’excès et le défaut. <span k=205A39><u class=ulw>Le</u> <u class=ulw>courage</u> <u class=ulw>en</u> <u class=ulw>est</u> <u class=ulw>un</u> <u class=ulw>exemple</u> <u class=ulw>:</u> </span>il se trouve entre la peur excessive et la témérité. <span k=205A39><u class=ulw>Aristote</u> <u class=ulw>a</u> <u class=ulw>pu</u> <u class=ulw>dire</u> <u class=ulw>que</u> </span>la vertu est un « juste milieu » entre deux excès.</div></div><div class=cpar><span class=cplab kb=24623E>Arg. 2</span><div class=cptxt><span k=205A39><u class=ulw>De</u> <u class=ulw>l’autre,</u> </span>il ne faut pas fuir les passions mais en éviter les mauvais usages. Éduquer ses passions, c’est les orienter vers de bonnes fins. <span k=205A39><u class=ulw>Aimer</u> <u class=ulw>le</u> <u class=ulw>football</u> </span>donne de la joie ; se battre avec les supporters adverses est un excès. <span k=205A39><u class=ulw>Descartes</u> <u class=ulw>écrit</u> <u class=ulw>que</u> </span>les passions sont « toutes bonnes de leur nature » et que nous n’avons à éviter « que leurs mauvais usages ou leurs excès ».</div></div><div class=saute k=24623E><i class=fa>&#xF338;</i> tu sautes deux lignes avant la conclusion</div><div class=cpar><span class=cplab kb=24623E>CONCL.</span><div class=cptxt><span k=205A39><u class=ulw>En</u> <u class=ulw>somme,</u> <u class=ulw>s’agissant</u> <u class=ulw>de</u> </span>la valeur des passions, <span k=205A39><u class=ulw>il</u> <u class=ulw>apparaît</u> <u class=ulw>que</u> </span>les passions ne sont un danger que lorsqu’elles échappent au contrôle de la raison. Kant et Spinoza montrent leur pouvoir d’asservissement, tandis que Hegel et Diderot rappellent qu’elles sont la source de l’énergie et de la création. <span k=205A39><u class=ulw>Chez</u> <u class=ulw>nous,</u> <u class=ulw>au</u> <u class=ulw>Cameroun,</u> </span>il importe d’éduquer les passions de la jeunesse plutôt que de les réprimer : orienter l’ambition et l’enthousiasme vers l’étude, le sport, la musique ou l’entrepreneuriat, tout en se défiant de la passion de l’argent facile qui pousse à la fraude.</div></div></div><p><a id=L-exo_D16_1></a></p><div class=exo><span class=exob kb=2E7D4F><i class=fa>&#xF303;</i> D16.1</span><div class=exot>Fais de ce sujet une dissertation philosophique.</div></div><div class=\"box callout tagged\" kb=FFF5DA><span class=tag kb=2E7D4F>SUJET</span><p><b>Sujet : </b>Une existence sans passions mérite-t-elle d’être vécue ?</p></div><h5 class=hthree k=2D7D4F><span class=hico><i class=fa>&#xF14A;</i></span><span class=hnum>16.3.1</span> Je prépare mon sujet (QCM : coche la bonne réponse)</h5><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=205A39><b>La thèse du sujet est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Convaincre, c’est vaincre : on cherche à imposer son point de vue à l’autre (rhétorique, Gorgias).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Une vie sans passions est la vie sage et libre : sans trouble ni esclavage (stoïciens, Kant).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) Le vrai est l’accord avec le réel, indépendamment de l’utilité : une erreur peut être utile (Thomas d’Aquin, Descartes).</span></label><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=205A39><b>L’antithèse du sujet est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Une vie sans passions est la vie sage et libre : sans trouble ni esclavage (stoïciens, Kant).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Une vie sans passions est terne et vide : les passions donnent sens et énergie (Hegel, Vauvenargues).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) Convaincre, c’est faire reconnaître librement une vérité : l’autre n’est pas vaincu mais éclairé (Socrate, Platon).</span></label><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>3.</span></span><div><span k=205A39><b>Le problème philosophique est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Le problème est la valeur de l’argumentation, qui consiste à savoir si argumenter sert à chercher la vérité ou seulement à l’emporter sur l’autre.</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Le problème est la valeur des passions, qui consiste à savoir si les passions sont un obstacle à la raison ou une force qu’il faut éduquer.</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) Le problème est la nature de la vérité, qui consiste à savoir si la vérité est absolue et universelle ou relative aux individus et aux cultures.</span></label><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>4.</span></span><div><span k=205A39><b>La problématique est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) La valeur de la vie tient-elle à l’absence de passions ou à leur intensité ?</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Une existence sans passions mérite-t-elle d’être vécue, voilà tout.</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) L’argumentation est-elle un combat pour l’emporter, ou une recherche commune du vrai ?</span></label><p><span k=205A39><b>Citations pour amener le sujet : </b></span>1. Opposée à la thèse (en premier) : Hegel : « Rien de grand ne s’est accompli dans le monde sans passion. » — 2. En faveur de la thèse : Kant : Les passions sont « des cancers pour la raison pure pratique ».</p><h5 class=hthree k=205A39><span class=hico><i class=fa>&#xF303;</i></span><span class=hnum>16.3.2</span> Ma rédaction (introduction, puis plan détaillé)</h5><textarea class=lignes rows=2></textarea><p><a id=L-exo_D16_2></a></p><div class=exo><span class=exob kb=2E7D4F><i class=fa>&#xF303;</i> D16.2</span><div class=exot>Fais de ce sujet une dissertation philosophique.</div></div><div class=\"box callout tagged\" kb=FFF5DA><span class=tag kb=2E7D4F>SUJET</span><p><b>Sujet : </b>Que penses-tu de cette affirmation de Vauvenargues : « Un homme sans passion est un roi sans sujets » ?</p></div><h5 class=hthree k=2D7D4F><span class=hico><i class=fa>&#xF14A;</i></span><span class=hnum>16.3.3</span> Je prépare mon sujet (QCM : coche la bonne réponse)</h5><ul class=numeros><li><span class=nu><span class=numlab k=24623E>1.</span></span><div><span k=205A39><b>La thèse du sujet est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Les passions sont la matière de l’action : sans elles, la raison n’a rien à gouverner (Vauvenargues, Hegel).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Le travail libère et humanise : il transforme la nature et l’homme (Hegel, Voltaire, Mounier).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) L’homme fait l’histoire par ses actions, ses choix et ses luttes (Sartre, Marx : les hommes font leur histoire).</span></label><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>2.</span></span><div><span k=205A39><b>L’antithèse du sujet est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Les passions sont des tyrans, non des sujets : elles gouvernent l’homme au lieu de lui obéir (Kant, stoïciens).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) L’histoire dépasse les hommes : conditions matérielles, Providence ou raison universelle (Marx, Hegel, Bossuet).</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) Les passions sont la matière de l’action : sans elles, la raison n’a rien à gouverner (Vauvenargues, Hegel).</span></label><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>3.</span></span><div><span k=205A39><b>Le problème philosophique est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Le problème est le moteur de l’histoire, qui consiste à savoir si l’histoire est conduite par les conditions matérielles et les luttes des hommes, ou par l’Esprit et la raison.</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Le problème est la finalité de l’art et du travail, qui consiste à savoir si ces activités servent seulement l’utilité ou si elles réalisent et libèrent l’homme.</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) Le problème est la valeur des passions, qui consiste à savoir si les passions sont un obstacle à la raison ou une force qu’il faut éduquer.</span></label><hr class=separgs><ul class=numeros><li><span class=nu><span class=numlab k=24623E>4.</span></span><div><span k=205A39><b>La problématique est :</b></span></div></li></ul><label class=qcm><input type=checkbox class=cb k=24623E><span>a) Les hommes sont-ils les auteurs de l’histoire ou ses instruments ?</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>b) Les passions sont-elles au service de l’homme, ou l’homme est-il à leur service ?</span></label><label class=qcm><input type=checkbox class=cb k=24623E><span>c) Que penses-tu de cette affirmation de Vauvenargues : « Un homme sans passion est un roi sans sujets », voilà tout.</span></label><p><span k=205A39><b>Citations pour amener le sujet : </b></span>1. Opposée à la thèse (en premier) : Kant : Les passions sont « des cancers pour la raison pure pratique ». — 2. En faveur de la thèse : Hegel : « Rien de grand ne s’est accompli dans le monde sans passion. »</p><h5 class=hthree k=205A39><span class=hico><i class=fa>&#xF303;</i></span><span class=hnum>16.3.4</span> Ma rédaction (introduction, puis plan détaillé)</h5><textarea class=lignes rows=2></textarea>","libre":true},{"id":"s21","kind":"chap","num":"17","titre":"La liberté et la responsabilité","sous":"Leçons 17 et 18 de la progression.","couleur":"B03B6B","genre":"Chapitre","html":""},{"id":"s22","kind":"chap","num":"18","titre":"La nature et la culture","sous":"Leçons 19 et 20 de la progression.","couleur":"1C6B96","genre":"Chapitre","html":""},{"id":"s23","kind":"chap","num":"19","titre":"L’art et le travail","sous":"Leçons 21 à 23 de la progression.","couleur":"1F8078","genre":"Chapitre","html":""},{"id":"s24","kind":"chap","num":"20","titre":"La science","sous":"Leçons 24 et 25 de la progression.","couleur":"BF522E","genre":"Chapitre","html":""},{"id":"s25","kind":"chap","num":"21","titre":"Les types de science","sous":"Leçons 26 à 28 de la progression.","couleur":"B8781F","genre":"Chapitre","html":""},{"id":"s26","kind":"chap","num":"22","titre":"La vérité","sous":"Leçons 29 et 30 de la progression.","couleur":"6B4C9C","genre":"Chapitre","html":""},{"id":"s27","kind":"chap","num":"23","titre":"L’espace et le temps","sous":"Leçons 31 et 32 de la progression.","couleur":"2E7D4F","genre":"Chapitre","html":""},{"id":"s28","kind":"chap","num":"24","titre":"L’existence et la mort","sous":"Leçons 33 et 34 de la progression.","couleur":"B03B6B","genre":"Chapitre","html":""},{"id":"s29","kind":"chap","num":"25","titre":"Dieu et la religion","sous":"Leçons 35 et 36 de la progression.","couleur":"1C6B96","genre":"Chapitre","html":""},{"id":"s30","kind":"chap","num":"26","titre":"L’homme et l’histoire","sous":"Leçons 37 et 38 de la progression.","couleur":"1F8078","genre":"Chapitre","html":""},{"id":"s31","kind":"part","num":"","titre":"Quatrième partie — S’entraîner à l’épreuve complète","sous":"","couleur":"1F2230","genre":"","html":""},{"id":"s32","kind":"corrige","num":"","titre":"Corrigés","sous":"","couleur":"7F2A4C","genre":"","html":""},{"id":"s33","kind":"biblio","num":"","titre":"Bibliographie des titres phares","sous":"","couleur":"7F2A4C","genre":"","html":""}]};
